"""Query parsing and room filtering helpers."""

from collections.abc import Mapping
from urllib.parse import parse_qs


_ALLOWED_PARAMS = {"q", "building", "feature", "minSeats"}


def parse_query(params):
    """Parse query parameters into normalized filter values.

    ``params`` may be a mapping (including the list-valued mapping returned by
    :func:`urllib.parse.parse_qs`) or a URL-encoded query string. For repeated
    parameters, the first value is used.
    """
    if params is None:
        params = {}
    elif isinstance(params, str):
        params = parse_qs(params, keep_blank_values=True)

    if not isinstance(params, Mapping):
        raise ValueError("Query parameters must be a mapping or URL-encoded string")

    filters = {}
    for key, raw_value in params.items():
        if key not in _ALLOWED_PARAMS:
            raise ValueError(f"Unknown query parameter: {key}")

        if isinstance(raw_value, (list, tuple)):
            raw_value = raw_value[0] if raw_value else ""

        if key == "minSeats":
            value = str(raw_value).strip()
            try:
                # int() accepts whitespace and signs; rejecting decimal or
                # other non-integer forms keeps validation predictable.
                if not value or not value.lstrip("+").isdigit():
                    raise ValueError
                min_seats = int(value)
            except (TypeError, ValueError):
                raise ValueError("minSeats must be a non-negative integer") from None
            if min_seats < 0:
                raise ValueError("minSeats must be a non-negative integer")
            filters[key] = min_seats
        else:
            filters[key] = str(raw_value).strip()

    return filters


def filter_rooms(rooms, filters):
    """Return rooms matching the supplied filters, preserving their order."""
    query = str(filters.get("q", "")).casefold()
    building = filters.get("building")
    feature = filters.get("feature")
    min_seats = filters.get("minSeats")

    matches = []
    for room in rooms:
        if query:
            name = room.get("name", "")
            room_building = room.get("building", "")
            if query not in str(name).casefold() and query not in str(room_building).casefold():
                continue

        if building is not None and room.get("building") != building:
            continue

        if feature is not None:
            room_features = room.get("features", room.get("feature", ()))
            if isinstance(room_features, str):
                has_feature = room_features == feature
            else:
                try:
                    has_feature = feature in room_features
                except TypeError:
                    has_feature = False
            if not has_feature:
                continue

        if min_seats is not None:
            try:
                seats = int(room.get("seats", 0))
            except (TypeError, ValueError):
                continue
            if seats < min_seats:
                continue

        matches.append(room)

    return matches

