import copy
import unittest

from app.query import filter_rooms, parse_query


class ParseQueryTests(unittest.TestCase):
    def test_parses_and_normalizes_supported_parameters(self):
        self.assertEqual(
            parse_query({"q": "  Atrium ", "building": " North ", "minSeats": " 24 "}),
            {"q": "Atrium", "building": "North", "minSeats": 24},
        )

    def test_parses_url_encoded_query_and_uses_first_repeated_value(self):
        self.assertEqual(
            parse_query("q=study+room&feature=whiteboard&feature=projector&minSeats=12"),
            {"q": "study room", "feature": "whiteboard", "minSeats": 12},
        )

    def test_rejects_unknown_parameters_and_invalid_min_seats(self):
        for params in ({"unknown": "value"}, {"minSeats": "2.5"}, {"minSeats": "-1"}):
            with self.subTest(params=params):
                with self.assertRaises(ValueError):
                    parse_query(params)

    def test_rejects_non_mapping_and_non_string_query_input(self):
        for params in (42, [("q", "study")]):
            with self.subTest(params=params):
                with self.assertRaises(ValueError):
                    parse_query(params)


class FilterRoomsTests(unittest.TestCase):
    def setUp(self):
        self.rooms = [
            {"name": "Atrium Study Hall", "building": "North", "features": ["whiteboard"], "seats": 30},
            {"name": "Quiet Room", "building": "North", "features": ["projector"], "seats": 12},
            {"name": "Atrium Lab", "building": "South", "features": ["whiteboard", "projector"], "seats": 24},
        ]

    def test_filters_matching_rooms(self):
        self.assertEqual(filter_rooms(self.rooms, {"building": "North"}), self.rooms[:2])

    def test_returns_empty_list_when_nothing_matches(self):
        self.assertEqual(filter_rooms(self.rooms, {"building": "West"}), [])

    def test_search_is_case_insensitive_for_names_and_buildings(self):
        self.assertEqual(filter_rooms(self.rooms, {"q": "aTrIuM"}), [self.rooms[0], self.rooms[2]])
        self.assertEqual(filter_rooms(self.rooms, {"q": "nOrTh"}), self.rooms[:2])

    def test_combines_search_building_feature_and_min_seats(self):
        self.assertEqual(
            filter_rooms(
                self.rooms,
                {"q": "atrium", "building": "South", "feature": "projector", "minSeats": 20},
            ),
            [self.rooms[2]],
        )

    def test_does_not_mutate_rooms_or_filters(self):
        rooms = copy.deepcopy(self.rooms)
        filters = {"q": "atrium", "minSeats": 20}
        original_filters = copy.deepcopy(filters)

        filter_rooms(rooms, filters)

        self.assertEqual(rooms, self.rooms)
        self.assertEqual(filters, original_filters)


if __name__ == "__main__":
    unittest.main()

