"""Load the project's room data."""

import json
from pathlib import Path


def load_rooms():
    """Return room records from the project's data/rooms.json file."""
    rooms_path = Path(__file__).resolve().parents[1] / "data" / "rooms.json"

    try:
        with rooms_path.open(encoding="utf-8") as rooms_file:
            rooms = json.load(rooms_file)
