                self.assertTrue(required.issubset(room), f'missing fields: {required - room.keys()}')

    def test_ids_are_strings_and_unique(self):
        ids = []
        for index, room in enumerate(self.rooms):
            with self.subTest(index=index):
                self.assertIsInstance(room, dict)
                self.assertIsInstance(room.get('id'), str)
                ids.append(room.get('id'))
        self.assertEqual(len(ids), len(set(ids)), 'room ids must be unique')

    def test_names_and_buildings_are_strings(self):
        for index, room in enumerate(self.rooms):
            with self.subTest(index=index):
                self.assertIsInstance(room, dict)
                self.assertIsInstance(room.get('name'), str)
                self.assertIsInstance(room.get('building'), str)

