"""Contract tests for the explicitly specified app/query.py module."""

import importlib.util
import io
import unittest
from pathlib import Path


PROJECT_ROOT = Path(__file__).resolve().parents[1]
MODULE_PATH = PROJECT_ROOT / "app" / "query.py"

# Load the target file directly, avoiding app/__init__.py and other project modules.
spec = importlib.util.spec_from_file_location("query_under_test", MODULE_PATH)
if spec is None or spec.loader is None:
    raise ImportError(f"Cannot load target module at {MODULE_PATH}")
query = importlib.util.module_from_spec(spec)
spec.loader.exec_module(query)


class QueryContractTests(unittest.TestCase):
    def setUp(self):
        self.rooms = [
            {"name": "Blue Hall", "building": "North Wing"},
            {"name": "Green Lab", "building": "South Wing"},
            {"name": "North Annex", "building": "East Wing"},
        ]

    def parse(self, params):
        return query.parse_query(params)

    def filter(self, records, params):
        return query.filter_rooms(records, self.parse(params))

    def assert_validation_error(self, operation):
        try:
            operation()
        except Exception as error:
            self.assertTrue(str(error).strip(), "validation error should have a useful message")
        else:
            self.fail("expected invalid query parameters to produce a validation error")

    def test_q_matches_name_without_case_sensitivity(self):
        self.assertEqual(self.filter(self.rooms, {"q": "bLuE hAlL"}), [self.rooms[0]])

    def test_q_matches_building_without_case_sensitivity(self):
        self.assertEqual(self.filter(self.rooms, {"q": "nOrTh WiNg"}), [self.rooms[0]])

    def test_nonmatching_q_returns_no_records(self):
        self.assertEqual(self.filter(self.rooms, {"q": "missing place"}), [])

    def test_building_filter_matches_and_nonmatches(self):
        self.assertEqual(self.filter(self.rooms, {"building": "South Wing"}), [self.rooms[1]])
        self.assertEqual(self.filter(self.rooms, {"building": "No Such Building"}), [])

    def test_empty_parameters_and_empty_q_keep_all_records_in_order(self):
        self.assertEqual(self.filter(self.rooms, {}), self.rooms)
        self.assertEqual(self.filter(self.rooms, {"q": ""}), self.rooms)

    def test_filtering_preserves_order_and_does_not_mutate_input(self):
        before = [record.copy() for record in self.rooms]
        result = self.filter(self.rooms, {"q": "wing"})
        self.assertEqual(result, [self.rooms[0], self.rooms[1], self.rooms[2]])
        self.assertEqual(self.rooms, before)
        self.assertEqual(result, self.rooms)

    def test_feature_parameter_is_recognized(self):
        # Record-level feature semantics are unspecified; verify accepted parameter parsing.
        self.parse({"feature": "projector"})

    def test_min_seats_accepts_nonnegative_integer(self):
        # Capacity record field/semantics are unspecified; verify accepted parameter parsing.
        self.parse({"minSeats": "0"})
        self.parse({"minSeats": "12"})

    def test_min_seats_rejects_malformed_and_negative_values(self):
        for value in ("many", "-1", "1.5"):
            with self.subTest(value=value):
                self.assert_validation_error(lambda value=value: self.parse({"minSeats": value}))

    def test_unknown_parameter_is_rejected(self):
        self.assert_validation_error(lambda: self.parse({"unexpected": "value"}))


class CountReportingRunner(unittest.TextTestRunner):
    def __init__(self, **kwargs):
        super().__init__(stream=io.StringIO(), verbosity=0, **kwargs)

    def run(self, test):
        result = super().run(test)
        passed = result.testsRun - len(result.failures) - len(result.errors) - len(result.skipped)
        print(f"PASSED: {passed}")
        if not result.wasSuccessful():
            for _, traceback in result.failures + result.errors:
                print(traceback)
        return result


