"""Independent HTTP contract checks for the rooms API."""

import json
import os
import socket
import subprocess
import sys
import time
import unittest
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode
from urllib.request import urlopen


def free_port():
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as listener:
        listener.bind(("127.0.0.1", 0))
        return listener.getsockname()[1]


class RoomsApiContractTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.port = free_port()
        env = os.environ.copy()
        env["PORT"] = str(cls.port)
        cls.server = subprocess.Popen(
            [sys.executable, "-m", "app.server"],
            env=env,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        cls.base_url = "http://127.0.0.1:{}".format(cls.port)

        deadline = time.monotonic() + 10
        while time.monotonic() < deadline:
            if cls.server.poll() is not None:
                raise RuntimeError("server exited before accepting requests")
            try:
                with urlopen(cls.base_url + "/api/rooms", timeout=0.3):
                    break
            except (URLError, OSError):
                time.sleep(0.05)
        else:
            cls.server.terminate()
            cls.server.wait(timeout=3)
            raise RuntimeError("server did not start on the PORT-selected local port")

    @classmethod
    def tearDownClass(cls):
        if getattr(cls, "server", None) is not None and cls.server.poll() is None:
            cls.server.terminate()
            try:
                cls.server.wait(timeout=3)
            except subprocess.TimeoutExpired:
                cls.server.kill()
                cls.server.wait(timeout=3)

    def request(self, path, params=None):
        url = self.base_url + path
        if params:
            url += "?" + urlencode(params)
        try:
            response = urlopen(url, timeout=2)
        except HTTPError as error:
            return error.code, error.read()
        with response:
            return response.status, response.read()

    def get_rooms(self, params=None):
        status, body = self.request("/api/rooms", params)
        self.assertEqual(status, 200)
        payload = json.loads(body.decode("utf-8"))
        self.assertIsInstance(payload, dict)
        self.assertIn("rooms", payload)
        self.assertIsInstance(payload["rooms"], list)
        for room in payload["rooms"]:
            self.assertIsInstance(room, dict)
            self.assertIn("name", room)
        return payload["rooms"]

    def test_port_environment_starts_local_server_and_rooms_response_is_json(self):
        rooms = self.get_rooms()
        self.assertGreater(len(rooms), 0)
        self.assertTrue(all(isinstance(room["name"], str) for room in rooms))

    def test_q_filters_room_name_case_insensitively(self):
        rooms = self.get_rooms({"q": "wILLoW"})
        self.assertEqual([room["id"] for room in rooms], ["synthetic-room-001"])

    def test_building_filter(self):
        rooms = self.get_rooms({"building": "Cedar Annex"})
        self.assertEqual([room["id"] for room in rooms], ["synthetic-room-002"])

    def test_feature_filter(self):
        rooms = self.get_rooms({"feature": "projector"})
        self.assertEqual([room["id"] for room in rooms], ["synthetic-room-001"])

    def test_min_seats_filter(self):
        rooms = self.get_rooms({"minSeats": "17"})
        self.assertEqual([room["id"] for room in rooms], ["synthetic-room-001"])

    def test_filters_can_be_combined(self):
        rooms = self.get_rooms(
            {"building": "Willow Hall", "feature": "whiteboard", "minSeats": "20"}
        )
        self.assertEqual([room["id"] for room in rooms], ["synthetic-room-001"])

    def test_no_matching_rooms_returns_empty_array_with_http_200(self):
        self.assertEqual(self.get_rooms({"q": "no-room-can-match-this"}), [])

    def test_invalid_min_seats_returns_http_400_json_error(self):
        status, body = self.request("/api/rooms", {"minSeats": "abc"})
        self.assertEqual(status, 400)
        self.assertIsInstance(json.loads(body.decode("utf-8")).get("error"), str)

    def test_unknown_query_parameter_returns_http_400_json_error(self):
        status, body = self.request("/api/rooms", {"unknownParam": "1"})
        self.assertEqual(status, 400)
        self.assertIsInstance(json.loads(body.decode("utf-8")).get("error"), str)

    def test_unknown_route_returns_404(self):
        status, _ = self.request("/api/not-a-route")
        self.assertEqual(status, 404)


if __name__ == "__main__":
    unittest.main()
